      "source": "def feature(s):\n    s = s or {}\n    sites = s.get('sites') or []\n    props = s.get('element_properties') or {}\n    n = len(sites)\n    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]\n    occ = [1.0 if t.get('occupancy') is None else t.get('occupancy') for t in sites]\n    counts = {}\n    for i in range(n):\n        if isfinite(occ[i]) and occ[i] > 0:\n            el = sites[i].get('element')\n            counts[el] = counts.get(el, 0.0) + occ[i]\n    z = sum(counts.values())\n    if z <= 0:\n        return nan\n    expected = 1.0 - sum((v / z) ** 2 for v in counts.values())\n    if expected <= 1e-12:\n        return 0.0\n    total = 0.0\n    unlike = 0.0\n    for bond in s.get('neighbors') or []:\n        i, j = bond.get('i'), bond.get('j')\n        d = bond.get('distance_A')\n        if i is None or j is None or not 0 <= i < n or not 0 <= j < n:\n            continue\n        a, b = radii[i], radii[j]\n        if a is None or b is None or not isfinite(a) or not isfinite(b) or a <= 0 or b <= 0:\n            continue\n        if d is None or not isfinite(d) or d <= 0 or occ[i] <= 0 or occ[j] <= 0:\n            continue\n        x = d / (1.25 * (a + b))\n        if x < 2.5:\n            w = occ[i] * occ[j] * exp(-(x ** 6))\n            total += w\n            if sites[i].get('element') != sites[j].get('element'):\n                unlike += w\n    return float(unlike / (total * expected)) if total > 0 else nan"
