      "source": "def feature(s):\n    s = s or {}\n    sites = s.get('sites') or []\n    matrix = (s.get('lattice') or {}).get('matrix')\n    n = len(sites)\n    if n == 0 or matrix is None or len(matrix) != 3:\n        return nan\n    occ = [1.0 if t.get('occupancy') is None else t.get('occupancy') for t in sites]\n    near = [inf for k in range(n)]\n    bonds = s.get('neighbors') or []\n    for bond in bonds:\n        i, j = bond.get('i'), bond.get('j')\n        d = bond.get('distance_A')\n        if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and d > 0 and occ[j] > 0:\n            near[i] = min(near[i], d)\n    tensors = np.zeros((n, 3, 3))\n    weights = np.zeros(n)\n    for bond in bonds:\n        i, j = bond.get('i'), bond.get('j')\n        d = bond.get('distance_A')\n        if i is None or j is None or not 0 <= i < n or not 0 <= j < n:\n            continue\n        if d is None or not isfinite(d) or d <= 0 or d > 1.6 * near[i] or occ[j] <= 0:\n            continue\n        fi, fj = sites[i].get('frac_coords'), sites[j].get('frac_coords')\n        image = bond.get('image')\n        if fi is None or fj is None or image is None:\n            continue\n        vector = [sum((fj[k] + image[k] - fi[k]) * matrix[k][a] for k in range(3)) for a in range(3)]\n        norm2 = sum(v * v for v in vector)\n        if not isfinite(norm2) or norm2 <= 0:\n            continue\n        w = occ[j] * exp(-((d / (1.2 * near[i])) ** 6))\n        weights[i] += w\n        for a in range(3):\n            for b in range(3):\n                tensors[i, a, b] += w * vector[a] * vector[b] / norm2\n    total = 0.0\n    z = 0.0\n    for i in range(n):\n        if weights[i] > 0 and isfinite(occ[i]) and occ[i] > 0:\n            q = sum(tensors[i, a, b] ** 2 for a in range(3) for b in range(3)) / weights[i] ** 2\n            total += occ[i] * max(0.0, min(1.0, (3.0 * q - 1.0) / 2.0))\n            z += occ[i]\n    return float(total / z) i